// tetris_state.c - generated by split_c.py from tetris.c
#include "tetris_priv.h"



//*****************************************************************************
// 2. GAME STATE
//*****************************************************************************


// Only LOCKED blocks live here. 0 = empty, otherwise a color index.
uint16_t tet_board[TETRIS_BOARD_H][TETRIS_BOARD_W];


// What the LCD is currently showing per cell. 0xFFFF = unknown, redraw.
uint16_t tet_shown[TETRIS_BOARD_H][TETRIS_BOARD_W];


TetrisPiece    tet_cur;
                  // the falling piece
int16_t  tet_nextType;
             // the piece that spawns next
int16_t  tet_shownNext;
            // next-piece preview currently on the LCD

uint32_t tet_score;

uint16_t tet_lines;

uint16_t tet_level;
                // 0..9

// Values currently shown in the side panel
uint32_t tet_shownScore;

uint16_t tet_shownLines;

uint16_t tet_shownLevel;


uint16_t tet_gravityCount;
         // frames since the piece last fell

// 7-bag randomizer
int16_t  tet_bag[7];

int16_t  tet_bagIdx;
               // next card to deal; 7 means "deck empty"

// Input / frame state that used to be locals in the old Tetris_Run() loop.
// It has to be file-static now because update() returns every frame.
uint16_t tet_frameNo;
              // paces the soft drop
int16_t  tet_hTimer;
               // countdown for left/right auto-repeat
int16_t  tet_prevMoveDir;
          // last frame's merged left/right input

// Game over state
bool     tet_gameOver;
             // true once the stack reached the top
uint16_t tet_gameOverTimer;
        // frames left in the "ignore input" window
bool     tet_gameOverDrawn;
        // GAME OVER text already on the LCD
int16_t  tet_gameOverRank;
         // high-score rank earned this game, -1 = none

// Line-clear animation: full rows flash white for TETRIS_CLEAR_FRAMES, THEN
// they are removed. The board is frozen while this runs.
bool     tet_clearing;

uint16_t tet_clearTimer;
           // frames left in the flash
uint32_t tet_clearMask;
            // bit r = row r is being cleared
int16_t  tet_clearCount;
           // rows being cleared (1..4)

// Banner over the playfield
uint16_t tet_bannerKind;
           // BANNER_NONE / _TETRIS / _RECORD
uint16_t tet_bannerTimer;
          // frames left on screen
bool     tet_bannerDirty;
          // box must be (re)drawn
bool     tet_bannerErase;
          // box just expired: repaint the board under it
bool     tet_recordShown;
          // NEW #1! already shown this game

// Title screen (Start / High Scores) is shown before each game.
bool     tet_inTitle;

uint16_t tet_titleView;
            // TITLE_VIEW_MENU or TITLE_VIEW_SCORES
uint16_t tet_titleSel;
             // highlighted row: 0 Start, 1 High Scores
int16_t  tet_titleStickY;
          // stick flick detection
bool     tet_titleDirtyFull;
       // whole title screen must be redrawn
uint16_t tet_titleDirtyRows;
       // bit i = menu rectangle i needs redrawing

// High scores: RAM copy of the saved top-5 list (best first, 0 = empty).
MemTetrisScores tet_hs;

MemTetrisNames  tet_hsn;
          // names matching s_hs.score[]
bool     tet_hsLoaded;


// Name entry (after a top-5 game over)
bool     tet_nameActive;

uint16_t tet_nameCur;
                      // cursor position 0..TETRIS_NAME_LEN-1
uint16_t tet_nameIdx[TETRIS_NAME_LEN];
     // index into s_nameCharset
bool     tet_nameDirtyFull;

bool     tet_nameDirtyBoxes;

int16_t  tet_nameStickX;

int16_t  tet_nameStickY;
